#!/usr/bin/env bash
set -euo pipefail

# GreenQUIC V22 OFF-mode full-results patch
#
# Goals:
#   * P2 can run as basic, off, or plus through GQ_MODE_OVERRIDE.
#   * The client always generates goodput and the same bundled summary for the
#     effective mode, instead of searching for a hard-coded basic manifest.
#   * OFF is a controlled maximum-performance baseline:
#       scaling_min_freq == scaling_max_freq for every active DPDK CPU.
#   * OFF frequency charts are generated by writing one verified
#     off_fixed_max frequency event per active DPDK CPU into the normal
#     timestamped transport timeline.
#   * Existing power1, RAPL and C-state collection remains enabled. P2 defaults
#     ENABLE_CSTATE_RECORD to 1 unless explicitly overridden.
#   * N active DPDK CPUs produce N frequency lanes and N C-state lanes.
#
# Apply this script on idex and tinyman. No MsQuic rebuild is required.

SUITE="${GQ_SUITE_ROOT:-/root/mohsen/greenquic_test_suite_v22}"
BIN="$SUITE/common/bin"
COMMON="$BIN/gq_common.sh"
BUNDLER="$BIN/bundle_run_results.py"
P2="$SUITE/test_cases/pretests/P2_goodput_basic_10GiB"
P2_CLIENT="$P2/run_client.sh"
P2_SERVER="$P2/run_server.sh"
COMPARE="$BIN/compare_p2_modes.py"
MARKER="GREENQUIC-V22-OFF-FULL-RESULTS-V1"

for file in "$COMMON" "$BUNDLER" "$P2_CLIENT" "$P2_SERVER"; do
    [[ -f "$file" ]] || {
        echo "ERROR: missing $file" >&2
        exit 1
    }
done

STAMP="$(date +%Y%m%d_%H%M%S)"
for file in "$COMMON" "$BUNDLER" "$P2_CLIENT" "$P2_SERVER"; do
    cp -a "$file" "${file}.before_off_full_results_${STAMP}"
done

python3 - "$COMMON" "$MARKER" <<'PY'
from __future__ import annotations

from pathlib import Path
import sys

path = Path(sys.argv[1])
marker = sys.argv[2]
text = path.read_text(encoding="utf-8")

if marker in text:
    print(f"Already patched: {path}")
    raise SystemExit(0)

helper_block = r'''
# GREENQUIC-V22-OFF-FULL-RESULTS-V1
# OFF is a controlled fixed-maximum-frequency baseline. The original cpufreq
# state is restored after the run. The synthetic log line is a configuration
# record used by the existing frequency postprocessor; after_khz is the value
# verified through scaling_min_freq/scaling_max_freq.
gq_expand_cpu_list() {
    python3 - "$1" <<'PY_CPU_LIST'
import sys

value = sys.argv[1].strip().replace(" ", "")
rows = []
for token in value.split(","):
    if not token:
        continue
    if "-" in token:
        first, last = token.split("-", 1)
        start, end = int(first), int(last)
        if end < start:
            raise SystemExit(f"invalid CPU range: {token}")
        rows.extend(range(start, end + 1))
    else:
        rows.append(int(token))
for cpu in sorted(set(rows)):
    print(cpu)
PY_CPU_LIST
}

gq_dpdk_cpus_from_config() {
    local cfg="$1" cpus
    cpus="$(sed -n 's/^[[:space:]]*GreenQuicDpdkLcores[[:space:]]*=[[:space:]]*//p' "$cfg" 2>/dev/null | tail -n 1 | tr -d '[:space:]')"
    [[ -n "$cpus" ]] || return 1
    printf '%s\n' "$cpus"
}

off_cpu_max_start() {
    local mode="$1" role="$2" cfg="$3" state_file="$4"
    [[ "$mode" == off ]] || return 0

    local cpus cpu dir governor minimum maximum target available current_min current_max failed=0
    cpus="$(gq_dpdk_cpus_from_config "$cfg")" || die "Cannot determine active DPDK CPUs for OFF mode from $cfg"
    : > "$state_file"

    while IFS= read -r cpu; do
        [[ -n "$cpu" ]] || continue
        dir="/sys/devices/system/cpu/cpu${cpu}/cpufreq"
        if [[ ! -d "$dir" ]]; then
            warn "CPU $cpu has no cpufreq sysfs directory."
            failed=1
            continue
        fi

        governor="$(cat "$dir/scaling_governor" 2>/dev/null || true)"
        minimum="$(cat "$dir/scaling_min_freq" 2>/dev/null || true)"
        maximum="$(cat "$dir/scaling_max_freq" 2>/dev/null || true)"
        target="$(cat "$dir/cpuinfo_max_freq" 2>/dev/null || true)"
        [[ "$target" =~ ^[0-9]+$ ]] || target="$maximum"

        if [[ ! "$minimum" =~ ^[0-9]+$ || ! "$maximum" =~ ^[0-9]+$ || ! "$target" =~ ^[0-9]+$ ]]; then
            warn "CPU $cpu has incomplete cpufreq values."
            failed=1
            continue
        fi

        printf '%s\t%s\t%s\t%s\n' "$cpu" "$governor" "$minimum" "$maximum" >> "$state_file"

        available="$(cat "$dir/scaling_available_governors" 2>/dev/null || true)"
        if [[ -w "$dir/scaling_governor" && " $available " == *" performance "* ]]; then
            printf '%s\n' performance > "$dir/scaling_governor"
        fi

        printf '%s\n' "$target" > "$dir/scaling_max_freq" 2>/dev/null || failed=1
        printf '%s\n' "$target" > "$dir/scaling_min_freq" 2>/dev/null || failed=1

        current_min="$(cat "$dir/scaling_min_freq" 2>/dev/null || true)"
        current_max="$(cat "$dir/scaling_max_freq" 2>/dev/null || true)"
        if [[ "$current_min" != "$target" || "$current_max" != "$target" ]]; then
            warn "CPU $cpu OFF maximum-frequency verification failed: min=$current_min max=$current_max target=$target"
            failed=1
        else
            log "OFF baseline CPU $cpu fixed at $((target / 1000)) MHz for $role."
        fi
    done < <(gq_expand_cpu_list "$cpus")

    if [[ "$failed" != 0 ]]; then
        off_cpu_max_stop "$state_file"
        if [[ "${GQ_REQUIRE_OFF_MAX_FREQ:-1}" == 1 ]]; then
            die "OFF mode requires every active DPDK CPU to be fixed at verified maximum frequency."
        fi
        warn "Continuing OFF mode without a fully verified fixed-maximum baseline."
    fi
}

off_cpu_max_stop() {
    local state_file="${1:-}"
    [[ -n "$state_file" && -f "$state_file" ]] || return 0

    local cpu governor minimum maximum dir
    while IFS=$'\t' read -r cpu governor minimum maximum; do
        [[ -n "$cpu" ]] || continue
        dir="/sys/devices/system/cpu/cpu${cpu}/cpufreq"
        [[ -d "$dir" ]] || continue

        # Lower the minimum first so restoring a lower maximum cannot violate
        # the min <= max constraint.
        [[ "$minimum" =~ ^[0-9]+$ && -w "$dir/scaling_min_freq" ]] && printf '%s\n' "$minimum" > "$dir/scaling_min_freq" 2>/dev/null || true
        [[ "$maximum" =~ ^[0-9]+$ && -w "$dir/scaling_max_freq" ]] && printf '%s\n' "$maximum" > "$dir/scaling_max_freq" 2>/dev/null || true
        [[ -n "$governor" && -w "$dir/scaling_governor" ]] && printf '%s\n' "$governor" > "$dir/scaling_governor" 2>/dev/null || true
    done < "$state_file"
}

off_cpu_max_emit_log() {
    local mode="$1" cfg="$2"
    [[ "$mode" == off ]] || return 0

    local cpus cpu dir minimum maximum current target result
    cpus="$(gq_dpdk_cpus_from_config "$cfg")" || return 0

    while IFS= read -r cpu; do
        [[ -n "$cpu" ]] || continue
        dir="/sys/devices/system/cpu/cpu${cpu}/cpufreq"
        minimum="$(cat "$dir/scaling_min_freq" 2>/dev/null || echo 0)"
        maximum="$(cat "$dir/scaling_max_freq" 2>/dev/null || echo 0)"
        current="$(cat "$dir/scaling_cur_freq" 2>/dev/null || echo 0)"
        target="$maximum"
        result=verified
        [[ "$minimum" == "$maximum" && "$maximum" =~ ^[0-9]+$ && "$maximum" -gt 0 ]] || result=unverified

        printf '[CPU %s] GreenQUIC FREQ policy_action=off_fixed_max api=sysfs_fixed_max result=%s ret=0 before_index=-1 after_index=-1 before_khz=%s after_khz=%s current_khz=%s cooldown_remaining_us=0 error=-\n' \
            "$cpu" "$result" "$target" "$target" "$current"
    done < <(gq_expand_cpu_list "$cpus")
}
'''

anchor = "\nrun_server() {\n"
if anchor not in text:
    raise SystemExit("ERROR: run_server anchor not found in gq_common.sh")
text = text.replace(anchor, "\n" + helper_block.strip() + "\n\nrun_server() {\n", 1)

# Server: keep OFF at fixed max for the entire measured lifetime.
server_energy = '    energy_start "$estart"\n'
server_start = '''    energy_start "$estart"
    GQ_SERVER_OFF_CPU_STATE="$runtime/off_cpu_max_${stamp}.state"
    off_cpu_max_start "$mode" server "$runtime/dpdk.ini" "$GQ_SERVER_OFF_CPU_STATE"
'''
if server_energy not in text:
    raise SystemExit("ERROR: server energy_start anchor not found")
text = text.replace(server_energy, server_start, 1)

server_finish_anchor = '        energy_finish "$GQ_SERVER_ESTART" "$GQ_SERVER_EOUT" "$GQ_SERVER_LABEL" || energy_rc=$?\n'
server_finish_new = server_finish_anchor + '        off_cpu_max_stop "${GQ_SERVER_OFF_CPU_STATE:-}"\n'
if server_finish_anchor not in text:
    raise SystemExit("ERROR: server cleanup anchor not found")
text = text.replace(server_finish_anchor, server_finish_new, 1)

server_launch = '''    cd "$runtime"
    GREENQUIC_CONFIG="$runtime/dpdk.ini" \\
    GREENQUIC_POWER_CONFIG="$runtime/powermng.ini" \\
    stdbuf -oL -eL "$INTEROP_SERVER_BIN" \\
        "-listen:$SERVER_LISTEN" "-port:$SERVER_PORT" \\
        "-root:$root" "-file:$cert" "-key:$key" -noexit \\
        2>&1 | python3 "$GQ_COMMON_DIR/bin/timestamp_tee.py" --raw-log "$logf" --timeline "$timelinef"
'''
server_launch_new = '''    cd "$runtime"
    (
        off_cpu_max_emit_log "$mode" "$runtime/dpdk.ini"
        export GREENQUIC_CONFIG="$runtime/dpdk.ini"
        export GREENQUIC_POWER_CONFIG="$runtime/powermng.ini"
        exec stdbuf -oL -eL "$INTEROP_SERVER_BIN" \\
            "-listen:$SERVER_LISTEN" "-port:$SERVER_PORT" \\
            "-root:$root" "-file:$cert" "-key:$key" -noexit
    ) 2>&1 | python3 "$GQ_COMMON_DIR/bin/timestamp_tee.py" --raw-log "$logf" --timeline "$timelinef"
'''
if server_launch not in text:
    raise SystemExit("ERROR: server launch block not found")
text = text.replace(server_launch, server_launch_new, 1)

# Client: start fixed max after all samplers are alive; preserve it through the
# configured post-transfer wait; restore after samplers stop.
client_energy = '    energy_start "$estart"\n    local rc=0 energy_rc=0 power_rc=0 msr_rc=0 cstate_rc=0 manifest_rc=0 cleanup_rc=0\n'
client_start = '''    energy_start "$estart"
    local off_cpu_state="$runtime/off_cpu_max_${stamp}.state"
    off_cpu_max_start "$mode" client "$runtime/dpdk.ini" "$off_cpu_state"
    local rc=0 energy_rc=0 power_rc=0 msr_rc=0 cstate_rc=0 manifest_rc=0 cleanup_rc=0
'''
if client_energy not in text:
    raise SystemExit("ERROR: client energy_start anchor not found")
text = text.replace(client_energy, client_start, 1)

client_emit_anchor = '''        export GREENQUIC_CONFIG="$runtime/dpdk.ini"
        export GREENQUIC_POWER_CONFIG="$runtime/powermng.ini"
        run_client_workload "$mode"
'''
client_emit_new = '''        export GREENQUIC_CONFIG="$runtime/dpdk.ini"
        export GREENQUIC_POWER_CONFIG="$runtime/powermng.ini"
        off_cpu_max_emit_log "$mode" "$runtime/dpdk.ini"
        run_client_workload "$mode"
'''
if client_emit_anchor not in text:
    raise SystemExit("ERROR: client workload anchor not found")
text = text.replace(client_emit_anchor, client_emit_new, 1)

client_finish_anchor = '    energy_finish "$estart" "$eout" "$TEST_ID client $mode" || energy_rc=$?\n'
client_finish_new = client_finish_anchor + '    off_cpu_max_stop "$off_cpu_state"\n'
if client_finish_anchor not in text:
    raise SystemExit("ERROR: client cleanup anchor not found")
text = text.replace(client_finish_anchor, client_finish_new, 1)

path.write_text(text, encoding="utf-8")
print(f"Patched: {path}")
PY

python3 - "$BUNDLER" "$MARKER" <<'PY'
from pathlib import Path
import sys

path = Path(sys.argv[1])
marker = sys.argv[2]
text = path.read_text(encoding="utf-8")

if marker in text:
    print(f"Already patched: {path}")
    raise SystemExit(0)

anchor = '    copy(runtime / "powermng.ini", details / f"{stem}_powermng_config.txt")\n'
insert = anchor + '''    copy(
        runtime / f"off_cpu_max_{stamp}.state",
        details / f"{stem}_off_cpu_max_original_state.txt",
    )
'''
if anchor not in text:
    raise SystemExit("ERROR: bundle runtime-config anchor not found")
text = text.replace(anchor, insert, 1)

# The frequency parser already recognizes the synthetic off_fixed_max line.
# Pass mode as metadata through the environment for chart titles/scripts that
# use it, without changing the existing CLI contract.
call = '''        subprocess.run([
            "python3", str(Path(__file__).with_name("frequency_trace.py")),
            "--timeline", str(timeline),
            "--prefix", str(frequency_prefix),
            "--role", args.role,
        ], check=True)
'''
replacement = '''        frequency_env = os.environ.copy()
        frequency_env["GQ_RESULT_MODE"] = args.mode
        subprocess.run([
            "python3", str(Path(__file__).with_name("frequency_trace.py")),
            "--timeline", str(timeline),
            "--prefix", str(frequency_prefix),
            "--role", args.role,
        ], check=True, env=frequency_env)
'''
if call not in text:
    raise SystemExit("ERROR: frequency postprocessor call not found")
text = text.replace(call, replacement, 1)

text += f"\n# {marker}\n"
path.write_text(text, encoding="utf-8")
print(f"Patched: {path}")
PY

cat > "$P2_CLIENT" <<'SH'
#!/usr/bin/env bash
set -euo pipefail

HERE="$(cd -- "$(dirname -- "$0")" && pwd)"
source "$HERE/config.env"

MODE="${GQ_MODE_OVERRIDE:-basic}"
case "$MODE" in
    off|basic|plus) ;;
    *) echo "ERROR: invalid GQ_MODE_OVERRIDE=$MODE" >&2; exit 2 ;;
esac

# P2 is a comparison pretest, so collect the same C-state visual by default in
# every mode. Set ENABLE_CSTATE_RECORD=0 explicitly to disable it.
export ENABLE_CSTATE_RECORD="${ENABLE_CSTATE_RECORD:-1}"

"$HERE/../../../common/bin/run_role.sh" client "$HERE" "$MODE" 0

manifest="$(
    find "$HERE/results" -maxdepth 1 -type f \
        -name "client_download_manifest_${MODE}_*.json" \
        -printf '%T@ %p\n' |
    sort -nr |
    head -n1 |
    cut -d' ' -f2-
)"
[[ -n "$manifest" && -f "$manifest" ]] || {
    echo "ERROR: latest client download manifest for mode=$MODE not found" >&2
    exit 2
}

base="$(basename "$manifest")"
stamp="${base#client_download_manifest_${MODE}_}"
stamp="${stamp%.json}"
energy="$HERE/results/client_energy_${MODE}_${stamp}.json"
client_log="$HERE/logs/client_${MODE}_${stamp}.log"

[[ -f "$energy" ]] || {
    echo "ERROR: exact client energy file not found: $energy" >&2
    exit 2
}
[[ -f "$client_log" ]] || {
    echo "ERROR: exact client log not found: $client_log" >&2
    exit 2
}

actual_bytes="$(python3 - "$manifest" <<'PY_BYTES'
import json
import sys

row = json.load(open(sys.argv[1], encoding="utf-8"))
print(int(row.get("total_bytes", 0)))
PY_BYTES
)"
[[ "$actual_bytes" -gt 0 ]] || {
    echo "ERROR: no downloaded payload bytes were recorded in $manifest" >&2
    exit 2
}
[[ "$actual_bytes" == "$PAYLOAD_BYTES" ]] || {
    echo "ERROR: expected $PAYLOAD_BYTES bytes, got $actual_bytes" >&2
    exit 2
}

goodput="$HERE/results/goodput_${MODE}_${stamp}.json"
python3 "$HERE/../../../common/bin/report_goodput.py" \
    --energy "$energy" \
    --client-log "$client_log" \
    --bytes "$actual_bytes" \
    --mode "$MODE" \
    --test-id "$TEST_ID" \
    --out "$goodput"

python3 "$HERE/../../../common/bin/bundle_run_results.py" \
    --test-dir "$HERE" \
    --role client \
    --mode "$MODE" \
    --stamp "$stamp"
SH
chmod +x "$P2_CLIENT"

cat > "$P2_SERVER" <<'SH'
#!/usr/bin/env bash
set -euo pipefail

HERE="$(cd -- "$(dirname -- "$0")" && pwd)"
source "$HERE/config.env"

MODE="${GQ_MODE_OVERRIDE:-basic}"
case "$MODE" in
    off|basic|plus) ;;
    *) echo "ERROR: invalid GQ_MODE_OVERRIDE=$MODE" >&2; exit 2 ;;
esac

# Keep the server and client comparison artifacts symmetric by default.
export ENABLE_CSTATE_RECORD="${ENABLE_CSTATE_RECORD:-1}"

"$HERE/../../../common/bin/run_role.sh" server "$HERE" "$MODE" 0
SH
chmod +x "$P2_SERVER"

cat > "$COMPARE" <<'PY'
#!/usr/bin/env python3
"""Compare the latest bundled P2 client OFF and BASIC results."""
from __future__ import annotations

import argparse
import json
from pathlib import Path


def latest_run(result_root: Path, mode: str) -> Path:
    rows = [
        path
        for path in result_root.glob(
            f"*__P2_goodput_basic_10GiB__client__{mode}*"
        )
        if path.is_dir() and (path / "details").is_dir()
    ]
    if not rows:
        raise SystemExit(
            f"ERROR: no bundled P2 client result found for mode={mode}"
        )
    return max(rows, key=lambda path: path.stat().st_mtime_ns)


def load_goodput(run_dir: Path) -> tuple[float, float, Path]:
    rows = list((run_dir / "details").glob("*_goodput.json"))
    if len(rows) != 1:
        raise SystemExit(
            f"ERROR: expected one goodput JSON in {run_dir / 'details'}"
        )
    path = rows[0]
    data = json.loads(path.read_text(encoding="utf-8"))
    primary = data.get("primary", data)
    return (
        float(primary.get("goodput_gbps_decimal", 0.0)),
        float(primary.get("duration_s", primary.get("elapsed_s", 0.0))),
        path,
    )


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument(
        "--test-dir",
        type=Path,
        default=Path(
            "/root/mohsen/greenquic_test_suite_v22/"
            "test_cases/pretests/P2_goodput_basic_10GiB"
        ),
    )
    args = parser.parse_args()

    result_root = args.test_dir.resolve() / "results"
    off_run = latest_run(result_root, "off")
    basic_run = latest_run(result_root, "basic")
    off_gbps, off_s, off_json = load_goodput(off_run)
    basic_gbps, basic_s, basic_json = load_goodput(basic_run)

    speed_delta = (
        (basic_gbps - off_gbps) / off_gbps * 100.0
        if off_gbps > 0.0
        else float("nan")
    )
    time_delta = (
        (basic_s - off_s) / off_s * 100.0
        if off_s > 0.0
        else float("nan")
    )

    print("\n=== P2 OFF vs BASIC client comparison ===")
    print(f"OFF:   {off_gbps:.6f} Gbit/s | {off_s:.6f} s")
    print(f"BASIC: {basic_gbps:.6f} Gbit/s | {basic_s:.6f} s")
    print(f"BASIC goodput relative to OFF: {speed_delta:+.2f}%")
    print(f"BASIC duration relative to OFF: {time_delta:+.2f}%")
    print(f"OFF run:   {off_run}")
    print(f"BASIC run: {basic_run}")
    print(f"OFF goodput JSON:   {off_json}")
    print(f"BASIC goodput JSON: {basic_json}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
PY
chmod +x "$COMPARE"

# Validate all modified files before reporting success.
bash -n "$COMMON" "$P2_CLIENT" "$P2_SERVER"
python3 -m py_compile "$BUNDLER" "$COMPARE"
grep -Fq "$MARKER" "$COMMON" || {
    echo "ERROR: common marker missing" >&2
    exit 1
}
grep -Fq "$MARKER" "$BUNDLER" || {
    echo "ERROR: bundler marker missing" >&2
    exit 1
}

echo
echo "PASS: OFF-mode full-results patch installed."
echo
echo "P2 now uses the effective mode everywhere:"
echo "  GQ_MODE_OVERRIDE=off   -> off manifest, goodput, charts, summary and folder"
echo "  no override            -> basic manifest, goodput, charts, summary and folder"
echo
echo "OFF baseline behavior:"
echo "  active DPDK CPUs are fixed at verified maximum frequency"
echo "  original governor/min/max values are restored after the run"
echo "  frequency SVG gets one off_fixed_max bar per active DPDK CPU"
echo
echo "Default P2 measurement set:"
echo "  goodput"
echo "  power1 whole-system charts"
echo "  package/DRAM RAPL charts"
echo "  C-state charts"
echo "  CPU-frequency charts"
echo "  identical bundled run summary structure"
echo
echo "No MsQuic rebuild is required."
